  /// Number of engine isolates this pool boots.
  final int workers;

  final AsyncEnginePool _pool;

  /// Whether [dispatch] is usable.
  bool get ready => _pool.ready;

  /// Boots the worker isolates; idempotent. Must run while the event loop
  /// is alive.
