  'processType': 'object',
  'envIsObject': true,
  'cwdIsString': true,
  'joined': 'a/b/c.txt',
  'baseName': 'z.md',
  'assertOk': true,
  'formatted': 'answer=42',
  'utf8ByteLen': 10,
