  'base64': true,
  'clockIsNumber': true,
  'uuidShape': true,
  'randomFilled': true,
  'cloneDeep': true,
  'buffer': {
    'typeofFn': true,
    'isUint8Array': true,
    'b64': 'aGVsbG8=',
    'hexRoundTrip': true,
    'latin1Hex': '68ff',
    'utf8ByteLen': 12,
    'le': 1,
    'be': 9,
    'slice': 'bc',
    'copyRoundTrip': true,
    'isBufferTrue': true,
    'isBufferFalse':
        true, // fixture value: `B.isBuffer(new Uint8Array(4)) === false`
