        File('test/fixtures/cross_runtime_conformance.js').readAsStringSync(),
        filename: 'cross_runtime_conformance.js',
        errMsg: errors,
      );
      if (errors.isNotEmpty) throw StateError(errors.first!);
      rt.eval('actionTimers(params)', errMsg: errors);
      if (errors.isNotEmpty) throw StateError(errors.first!);
