    'q': '1',
    'xDecoded': ' ',
    'getAllA': '1|2',
    'bDecoded': 'x y',
    'appendForm': 'k=a+b',
    'canParse': true,
  },
  'utilExtras': {
    'inspectString': "'hi'",
    'inspectNumber': '42',
    'isArray': true,
    'isString': true,
    'hasTime': true,
  },
  'osProcess': {
    'osEolType': 'string',
    'osPlatformType': 'string',
    'osArchType': 'string',
    'osHomedirType': 'string',
    'nextTickType': 'function',
    'hrtimeType': 'function',
    'argvIsArray': true,
    'pidIsNumber': true,
    'exitIsFunction': true,
  },
  'intl': {
    'numberFormat': true,
    'dateTimeFormat': true,
    'canonicalLocales': true,
  },
  'events': {
    'got': 't1,o',
    'emitReturnNoListener': true,
    'hasOff': true,
    'listenerCount': 1,
  },
  'fetchShapes': {
    'fetchTypeof': 'function',
    'headerGet': 'b',
    'headerHas': true,
    'responseType': 'function',
    'callStatus': 200,
    'callHeader': 'y',
    'callBody': true,
  },
  'stubGuards': true,
