/// Parsed `runAsync(fn, args)` host-call arguments.
/// The worker-shutdown control message on the spawn inbox.
const String _shutdownMessage = 'shutdown';

class _DispatchArgs {
  const _DispatchArgs({this.fnSource, this.argsJson, this.error});

